<form method="post" class="card" data-protect-unsaved><?= $csrf->field() ?><div class="card-heading"><div><p class="section-kicker">Checkout</p><h2>Manual payment methods</h2><p class="card-subtitle">No gateway is used. Orders remain payment pending until you confirm receipt.</p></div><span class="badge neutral">Venmo · PayPal · Cash App</span></div><div class="payment-method-grid"><?php foreach($catalog as $key=>$meta): $row=is_array($saved[$key]??null)?$saved[$key]:[]; ?><section class="payment-method-card"><label class="toggle-control"><input type="checkbox" name="payments[<?= e_attr($key) ?>][enabled]" <?= !empty($row['enabled'])?'checked':'' ?>><span class="toggle-track" aria-hidden="true"></span><span><strong><?= e($meta['label']) ?></strong><small>Offer at checkout</small></span></label><label>Payment handle or customer instructions<textarea name="payments[<?= e_attr($key) ?>][instructions]" rows="4" maxlength="500" placeholder="<?= e_attr($meta['placeholder']) ?>"><?= e($row['instructions']??'') ?></textarea></label></section><?php endforeach; ?></div><section class="inline-notice"><strong>Fulfillment supplied by the industry module</strong><span><?= e(implode(', ',array_map('ucfirst',$fulfillment))) ?></span></section><div class="action-bar"><span>Disabled methods never appear to customers.</span><button class="btn">Save payment methods</button></div></form>
